def prime_length(string):
    length = len(string)
    if length < 2:
        return False
    for i in range(2, int(length**0.5) + 1):
        if length % i == 0:
            return False
    return True

def add(lst):
    total = 0
    for i in range(1, len(lst), 2):  # odd indices (1, 3, 5, ...)
        if lst[i] % 2 == 0:  # even element
            total += lst[i]
    return total

