def anti_shuffle(s):
    words = s.split()
    result = []
    for word in words:
        sorted_word = ''.join(sorted(word))
        result.append(sorted_word)
    return ' '.join(result)

def get_row(lst, x):
    coordinates = []
    for i, row in enumerate(lst):
        for j, val in enumerate(row):
            if val == x:
                coordinates.append((i, j))
    coordinates.sort(key=lambda coord: coord[0])  # Sort by rows ascending
    coordinates.sort(key=lambda coord: coord[1], reverse=True)  # Sort by columns descending within same row
    return coordinates

def sort_array(array):
    if len(array) <= 1:
        return array[:]

    first = array[0]
    last = array[-1]
    if (first + last) % 2 == 1:
        return sorted(array)
    else:
        return sorted(array, reverse=True)

def encrypt(s):
    result = []
    for char in s:
        if char.isalpha():
            shift = (2 * 2) % 26  # Rotate by 4 positions
            if char.islower():
                start = ord('a')
            else:
                start = ord('A')
            encrypted_char = chr(start + (ord(char) - start + shift) % 26)
            result.append(encrypted_char)
        else:
            result.append(char)
    return ''.join(result)

def encode(message):
    vowels = 'aeiou'
    result = []
    for char in message:
        if char.isalpha():
            # Swap case
            if char.islower():
                char = char.upper()
            else:
                char = char.lower()

            # If it's a vowel, replace with the letter 2 places ahead
            if char in vowels:
                # Find the position in alphabet
                # 'a' -> 0, 'b' -> 1, ..., 'z' -> 25
                pos = ord(char) - ord('a')
                new_pos = (pos + 2) % 26
                new_char = chr(ord('a') + new_pos)
                char = new_char

        result.append(char)

    return ''.join(result)

