def check_dict_case(dict):
    if not dict:
        return False

    keys = list(dict.keys())
    if len(keys) == 0:
        return False

    # Check if all keys are strings
    for key in keys:
        if not isinstance(key, str):
            return False

    # Check if all keys are lowercase or all are uppercase
    all_lower = all(key.islower() for key in keys)
    all_upper = all(key.isupper() for key in keys)

    return all_lower or all_upper

def count_up_to(n):
    if n <= 2:
        return []

    def is_prime(num):
        if num < 2:
            return False
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                return False
        return True

    result = []
    for i in range(2, n):
        if is_prime(i):
            result.append(i)
        if len(result) == n - 1:  # We only need n primes, but we can stop early if we have enough
            break

    return result

def choose_num(x, y):
    if x > y:
        return -1
    # Start from the largest number in the range and go down
    for num in range(y, x - 1, -1):
        if num % 2 == 0:
            return num
    return -1

