    return sorted(result)

def even_odd_palindrome(n):
    even_count = 0
    odd_count = 0

    for i in range(1, n + 1):
        # Check if i is a palindrome
        s = str(i)
        if s == s[::-1]:
            # Check if it's even or odd
            if i % 2 == 0:
                even_count += 1
            else:
                odd_count += 1

    return (even_count, odd_count)

def count_nums(arr):
    count = 0
    for num in arr:
        # Convert to string to process digits
        s = str(num)
        # If negative, the first digit is negative
        if s[0] == '-':
            signed_digits = [int(d) for d in s[1:]]
            signed_digits = [-signed_digits[0]] + signed_digits[1:]
        else:
            signed_digits = [int(d) for d in s]

        # Sum of signed digits
        digit_sum = sum(signed_digits)
        if digit_sum > 0:
            count += 1
    return count

def move_one_ball(arr):
    if len(arr) == 0:
        return True

    n = len(arr)
    # Check if the array is already sorted
    if all(arr[i] <= arr[i+1] for i in range(n-1)):
        return True

    # Try all possible right shifts
    for shift in range(1, n + 1):
        # Perform right shift 'shift' times
        shifted = arr[-shift:] + arr[:-shift]
        # Check if the shifted array is sorted
        if all(shifted[i] <= shifted[i+1] for i in range(n-1)):
            return True

    return False

def exchange(lst1, lst2):
    odd_in_lst1 = len(lst1) - sum(1 for x in lst1 if x % 2 == 0)
    even_in_lst2 = sum(1 for x in lst2 if x % 2 == 0)

    # We need to replace all odd numbers in lst1 with even numbers from lst2
    # We can get at most len(lst2) even numbers from lst2
    # So we need at least odd_in_lst1 even numbers from lst2
    if even_in_lst2 >= odd_in_lst1:
        return "YES"
    else:
        return "NO"

def histogram(test):
    if not test:
        return {}

    # Split the string into individual letters
    letters = test.split()
    # Count occurrences of each letter
    count = {}
    for letter in letters:
        count[letter] = count.get(letter, 0) + 1

    # Find the maximum count
    max_count = max(count.values())

    # Find all letters with the maximum count
    result = {}
    for letter, freq in count.items():
        if freq == max_count:
            result[letter] = freq

    return result

def reverse_delete(s, c):
    # Create a new string by keeping only characters in s that are not in c
    result = ''.join(char for char in s if char not in c)

    # Check if the result is a palindrome
    is_palindrome = result == result[::-1]

    return (result, is_palindrome)

def max_fill(grid, capacity):
    import math

    total_water = 0
    for row in grid:
        total_water += sum(row)

    # Each bucket can hold 'capacity' units of water
    # So number of bucket trips needed is ceiling of total_water / capacity
    return math.ceil(total_water / capacity)

