    s1, s2 = lst
    # Check if we can make a balanced string by concatenating in some order
    # Try both orders: s1 + s2 and s2 + s1
    def is_balanced(s):
        count = 0
        for c in s:
            if c == '(':
                count += 1
            else:
                count -= 1
            if count < 0:
                return False
        return count == 0

    # Check both concatenations
    if is_balanced(s1 + s2) or is_balanced(s2 + s1):
        return 'Yes'
    else:
        return 'No'

