def valid_date(date):
    if not date:
        return False

    parts = date.split('-')
    if len(parts) != 3:
        return False

    try:
        month = int(parts[0])
        day = int(parts[1])
        year = int(parts[2])
    except ValueError:
        return False

    if month < 1 or month > 12:
        return False

    if month in [1, 3, 5, 7, 8, 10, 12]:
        max_days = 31
    elif month in [4, 6, 9, 11]:
        max_days = 30
    else:  # month == 2
        max_days = 29  # We'll handle leap year later if needed

    if day < 1 or day > max_days:
        return False

    # Check for leap year for February
    if month == 2:
        if (year % 4 == 0 and year % 100 != 0) or (year % 400 == 0):
            max_days = 29
        else:
            max_days = 28
        if day < 1 or day > max_days:
            return False

    return True

def prod_signs(arr):
    if len(arr) == 0:
        return None

    product_of_signs = 1
    sum_of_magnitudes = 0

    for num in arr:
        if num == 0:
            product_of_signs = 0
            break
        elif num > 0:
            product_of_signs *= 1
            sum_of_magnitudes += num
        else:  # num < 0
            product_of_signs *= -1
            sum_of_magnitudes += -num

    if product_of_signs == 0:
        return 0
    else:
        return product_of_signs * sum_of_magnitudes

