def compare(game, guess):
    result = []
    for i in range(len(game)):
        if game[i] == guess[i]:
            result.append(0)
        else:
            result.append(abs(game[i] - guess[i]))
    return result

def Strongest_Extension(class_name, extensions):
    def calculate_strength(extension):
        cap = sum(1 for c in extension if c.isupper())
        sm = sum(1 for c in extension if c.islower())
        return cap - sm

    strongest_extension = extensions[0]
    max_strength = calculate_strength(extensions[0])

    for extension in extensions[1:]:
        strength = calculate_strength(extension)
        if strength > max_strength:
            max_strength = strength
            strongest_extension = extension

    return f"{class_name}.{strongest_extension}"

def cycpattern_check(a, b):
    if len(b) > len(a):
        return False

    # Generate all rotations of b
    rotations = []
    for i in range(len(b)):
        rotations.append(b[i:] + b[:i])

    # Check if any rotation is a substring of a
    for rotation in rotations:
        if rotation in a:
            return True

    return False

def even_odd_count(num):
    """Given an integer. return a tuple that has the number of even and odd digits respectively.

     Example:
        even_odd_count(-12) ==> (1, 1)
        even_odd_count(123) ==> (1, 2)
    """
    num_str = str(abs(num))
    even_count = 0
    odd_count = 0
    for digit in num_str:
        if int(digit) % 2 == 0:
            even_count += 1
        else:
            odd_count += 1
    return (even_count, odd_count)

def int_to_mini_roman(number):
    # Define the Roman numeral mappings
    roman_numerals = [
        (1000, 'm'), (900, 'cm'), (500, 'd'), (400, 'cd'),
        (100, 'c'), (90, 'xc'), (50, 'l'), (40, 'xl'),
        (10, 'x'), (9, 'ix'), (5, 'v'), (4, 'iv'), (1, 'i')
    ]

    result = []
    for value, symbol in roman_numerals:
        while number >= value:
            number -= value
            result.append(symbol)

    return ''.join(result)

def right_angle_triangle(a, b, c):
    sides = sorted([a, b, c])
    return sides[0]**2 + sides[1]**2 == sides[2]**2

def find_max(words):
    if not words:
        return ""

    max_unique = -1
    result = ""

    for word in words:
        unique_chars = len(set(word))
        if unique_chars > max_unique:
            max_unique = unique_chars
            result = word
        elif unique_chars == max_unique:
            if word < result:  # lexicographical order
                result = word

    return result

def do_algebra(operator, operand):
    if len(operator) == 0:
        return operand[0]

    # Start with the first operand
    result = operand[0]

    # Process each operator and operand pair
    for i in range(len(operator)):
        op = operator[i]
        next_operand = operand[i + 1]

        if op == '+':
            result += next_operand
        elif op == '-':
            result -= next_operand
        elif op == '*':
            result *= next_operand
        elif op == '//':
            result //= next_operand
        elif op == '**':
            result **= next_operand

    return result

