def solve(s):
    # Check if string contains any letters
    has_letters = any(c.isalpha() for c in s)

    if not has_letters:
        # Reverse the string if no letters
        return s[::-1]

    # Reverse case of each letter
    result = []
    for c in s:
        if c.isalpha():
            if c.islower():
                result.append(c.upper())
            else:
                result.append(c.lower())
        else:
            result.append(c)

    return ''.join(result)

