    end = max(a, b)

    # Collect even digits from numbers in the range [start, end]
    even_digits = []
    for num in range(start, end + 1):
        # Convert number to string to process each digit
        for digit in str(num):
            # Check if the digit is even (0, 2, 4, 6, 8)
            if int(digit) % 2 == 0:
                even_digits.append(int(digit))

    # Remove duplicates and sort
    even_digits = sorted(set(even_digits))

    return even_digits
